const PW_CODE=`import { test, expect } from '@playwright/test';
import { BomManagementPage } from '../pages/bom-management.page';
import { BomTreeComponent } from '../components/bom-tree.component';
import { LoginPage } from '../pages/login.page';

test.describe('BOM Hierarchy Depth Validation', () => {
  let bomPage: BomManagementPage;
  let bomTree: BomTreeComponent;

  test.beforeEach(async ({ page }) => {
    const loginPage = new LoginPage(page);
    await loginPage.loginAs('bom_manager');
    bomPage = new BomManagementPage(page);
    bomTree = new BomTreeComponent(page);
    await bomPage.navigate();
  });

  test('TC-004: Should reject nesting beyond max depth',
    async ({ page }) => {
    // Step 1: Create parent assembly
    await bomPage.clickCreateNewBom();
    await bomPage.fillAssemblyDetails({
      name: 'ASSY-TEST-001',
      type: 'Assembly',
      description: 'Depth validation test'
    });
    await bomPage.save();
    await expect(bomPage.successToast).toBeVisible();

    // Step 2-4: Build hierarchy to max depth (15)
    let parentId = await bomPage.getCreatedBomId();
    for (let level = 1; level <= 15; level++) {
      await bomTree.addChildAssembly(parentId, {
        name: \`SUB-ASSY-L\${level}\`,
        type: 'Sub-Assembly'
      });
      parentId = await bomTree.getLastAddedNodeId();
      await expect(bomTree.getNodeAtLevel(level))
        .toBeVisible();
    }

    // Step 5: Attempt level 16 (should fail)
    await bomTree.addChildAssembly(parentId, {
      name: 'SUB-ASSY-L16-INVALID',
      type: 'Sub-Assembly'
    });
    await expect(bomPage.validationError).toContainText(
      'Maximum nesting depth (15) exceeded'
    );

    // Step 6: Verify hierarchy intact
    const treeDepth = await bomTree.getMaxDepth();
    expect(treeDepth).toBe(15);
  });
});`;

