const DA_DATA={stats:[{label:"Customer Defects",value:"156",icon:"bug"},{label:"Matched to Tests",value:"109",icon:"check"},{label:"Coverage Gaps",value:"47",icon:"target"},{label:"Gap Rate",value:"30.1%",icon:"shield"}],defects:[{id:"CUST-4821",title:"BOM export times out for 800+ component assemblies",customer:"Acme Mfg",severity:"critical",module:"BOM",match:"gap",tests:0,gap:"No performance test for >500 components",rec:"Generate boundary test for 500, 800, 1000+ components"},{id:"CUST-4819",title:"ECO approval breaks when approver deactivated mid-workflow",customer:"GlobalParts",severity:"high",module:"ECO",match:"partial",tests:2,gap:"Tests cover happy path only, not mid-workflow deactivation",rec:"Add negative test: deactivate approver during active ECO"},{id:"CUST-4815",title:"Part revision displays incorrectly after rollback",customer:"TechFab",severity:"high",module:"Parts",match:"covered",tests:3,gap:null,rec:"TC-187 covers this — investigate environment drift"},{id:"CUST-4812",title:"BOM copy loses attributes on nested sub-assemblies beyond level 3",customer:"Acme Mfg",severity:"medium",module:"BOM",match:"gap",tests:0,gap:"BOM copy tests only validate level 1-2 attributes",rec:"Extend to validate attributes at levels 3, 5, and max depth"},{id:"CUST-4808",title:"MRP includes obsolete parts when filter set to Active Only",customer:"DynaMfg",severity:"critical",module:"MRP",match:"partial",tests:1,gap:"Test validates filter UI but not calculation output",rec:"Add assertion verifying obsolete parts excluded from demand"},{id:"CUST-4805",title:"Config comparison crashes with >50 attributes",customer:"TechFab",severity:"medium",module:"Config",match:"gap",tests:0,gap:"No stress test for high attribute count comparison",rec:"Generate boundary test: 20, 50, 100 attributes"}],gapsByModule:[{module:"BOM",total:42,gaps:18,rate:43},{module:"ECO",total:28,gaps:8,rate:29},{module:"MRP",total:31,gaps:9,rate:29},{module:"Parts",total:22,gaps:4,rate:18},{module:"Config",total:18,gaps:6,rate:33},{module:"Change",total:15,gaps:2,rate:13}],gapCats:[{cat:"Boundary / Scale",count:16,pct:34},{cat:"Negative / Error Path",count:11,pct:23},{cat:"Integration",count:8,pct:17},{cat:"State Transition Edge",count:7,pct:15},{cat:"Data / Attribute Depth",count:5,pct:11}],trend:[{month:"Oct",defects:28,gaps:14},{month:"Nov",defects:24,gaps:10},{month:"Dec",defects:31,gaps:12},{month:"Jan",defects:22,gaps:7},{month:"Feb",defects:26,gaps:6},{month:"Mar",defects:25,gaps:5}]};

