<div {...rv("hb")}><div className="inline-flex items-center gap-2 px-4 py-2 rounded-full border border-cyan-500/25 bg-cyan-500/8 text-cyan-400 text-xs font-medium tracking-wider uppercase mb-8"><span className="w-1.5 h-1.5 rounded-full bg-cyan-400" style={{animation:"pglow 2s ease-in-out infinite"}}/>AI-Powered QA for Digital Manufacturing</div></div>
